        "example": "#!/bin/bash\n# 算术运算演示 arith.sh\n\na=10\nb=3\necho \"加: $((a + b))\"       # 13\necho \"减: $((a - b))\"       # 7\necho \"乘: $((a * b))\"       # 30\necho \"除: $((a / b))\"       # 3 (整数除法)\necho \"取余: $((a % b))\"     # 1\necho \"幂: $((a ** 2))\"      # 100\n\n# 自增\ncount=0\n((count++))                  # 1\n((count += 10))              # 11\necho \"count = $count\"\n\n# 随机数\necho \"随机(0-99): $((RANDOM % 100))\"\n\n# bc 小数运算\necho \"3.14 * 2 = $(echo \"3.14 * 2\" | bc)\"       # 6.28\necho \"10/3 = $(echo \"scale=2; 10/3\" | bc)\"       # 3.33\n\n# 数字比较\nif ((a > b)); then\n    echo \"$a > $b\"           # 10 > 3\nfi"
